//! Which directions a Mapping defines, and whether transforming in each is
//! an error, match C for Mappings whose definedness depends on more than
//! their coefficients: a PolyMap with unequal numbers of inputs and outputs
//! (polymap.c `GetIterInverse`, `SetIterInverse`), a MatrixMap holding a bad
//! element (matrixmap.c `InvertMatrix`), an inverted SwitchMap (mapping.c
//! `GetTranForward`) and an NCP WcsMap (wcsmap.c `Map`), each with a control.
//! The MatrixMaps are also built here from the matrices C was given.
//!
//! `tran_definedness_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/tran_definedness_probe.c`.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "tran_definedness_oracle/cases.rs"]
mod cases;

use std::panic::{AssertUnwindSafe, catch_unwind};

use starlink_ast::constants::BAD_VALUE;
use starlink_ast::coords::PointSet;
use starlink_ast::mappings::{Mapping, MatrixMap};
use starlink_ast::{AnyObject, from_native_string};

fn text(lines: &[&str]) -> String {
    let mut s = lines.join("\n");
    s.push('\n');
    s
}

/// Whether transforming one point in the given direction fails. A panic
/// counts as a failure to report, not as C's error.
fn tran_fails(map: &dyn Mapping, forward: bool) -> Result<bool, String> {
    let n = if forward { map.nin() } else { map.nout() };
    let point: Vec<f64> = (1..=n).map(|i| 0.1 * i as f64).collect();
    let pts = PointSet::from_rows([point]);
    catch_unwind(AssertUnwindSafe(|| map.transform(&pts, forward).is_err()))
        .map_err(|_| "panicked".to_string())
}

#[test]
fn definedness_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(name, dump, fwd, inv, ffail, ifail, iterfail) in cases::CASES {
        let obj = from_native_string(&text(dump)).unwrap();
        let map = obj.as_mapping().expect("a Mapping");
        let got = (
            map.has_forward(),
            map.has_inverse(),
            tran_fails(map, true),
            tran_fails(map, false),
        );
        let want = (fwd, inv, Ok(ffail), Ok(ifail));
        if got != want {
            failures.push(format!(
                "{name}: (TranForward, TranInverse, forward fails, inverse fails) \
                 {got:?}, C gives {want:?}"
            ));
        }
        if let AnyObject::PolyMap(mut poly) = obj {
            let got = poly.set_iter_inverse(true).is_err();
            if got != iterfail {
                failures.push(format!(
                    "{name}: setting IterInverse fails {got}, C {iterfail}"
                ));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn built_matrixmaps_match_the_c_library() {
    let built = [
        (
            "matrixmap_full_bad",
            ndarray::array![[1.0, BAD_VALUE], [0.0, 1.0]],
        ),
        ("matrixmap_full", ndarray::array![[1.0, 2.0], [0.0, 1.0]]),
    ];
    for (name, matrix) in built {
        let &(_, _, fwd, inv, ffail, ifail, _) =
            cases::CASES.iter().find(|c| c.0 == name).expect("a case");
        let map = MatrixMap::new(matrix).unwrap();
        let got = (
            map.has_forward(),
            map.has_inverse(),
            tran_fails(&map, true),
            tran_fails(&map, false),
        );
        assert_eq!(got, (fwd, inv, Ok(ffail), Ok(ifail)), "{name}");
    }
}
